  const dorm = /(寮|社宅|借上|住宅)[^。\/ ]{0,6}(なし|無し|はありません|無)/.test(hs) ? 'No' : /(寮|社宅|借上げ?社宅|住宅手当|住宅補助)/.test(hs) ? 'Yes' : 'Unknown';
