// Verify (WF03): read back every property we changed and compare (CJK corruption / silent failure check).
const plain = (arr) => (arr || []).map((x) => x.plain_text || '').join('');
const nz = (s) => String(s === null || s === undefined ? '' : s).replace(/\r/g, '').trim();
const out = [];
const inputs = $input.all();
for (let k = 0; k < inputs.length; k++) {
  const it = inputs[k]; let job = {}; let patched = {};
  try { job = $('Organize').itemMatching(k).json; } catch (e) { job = {}; }
